head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellChecked]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Body Cell 의 체크 상태를 설정합니다.",
    "validation" : [
        "setCellChecked() 메소드 실행 시 DataList 값이 변경되므로 onbeforecelldatachange 이벤트가 발생하며 false 를 반환하면 변경이 취소됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // onbeforecelldatachange 동작 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="setCellChecked 실행 시 chk Cell 값이 바뀌므로 DataList 의 onbeforecelldatachange 가 발생 / par_cancel=취소 면 핸들러가 false 반환하여 값 변경 취소"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    //  - chk  : checkbox(binary) 원본값 1/0 → setCellChecked 대상
    //  - name : text 컬럼
    //  - memo : text 컬럼
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // Row0/Row2 = 체크(trueValue "1"), Row1/Row3 = 미체크(falseValue "0")
    let jsonData = [
        { "chk": "1", "name": "John", "memo": "메모0" },
        { "chk": "0", "name": "Jane", "memo": "메모1" },
        { "chk": "1", "name": "Mike", "memo": "메모2" },
        { "chk": "0", "name": "Amy",  "memo": "메모3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // onbeforecelldatachange 이벤트를 DataList 에 바인딩
    //  - setCellChecked 실행 시 chk Cell 값이 바뀌면서 이 이벤트가 발생
    dlt_bind.bind("onbeforecelldatachange", scwin.dlt_bind_onbeforecelldatachange);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 3컬럼)
    // 마지막 memo 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:660px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setCellChecked onbeforecelldatachange 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="chk(checkbox)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol2" value="name(text)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="memo(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : chk (checkbox, valueType=binary) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="160" style="" inputType="checkbox" valueType="binary" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    // index 1 : name (text)
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 2 : memo (text) - width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// onbeforecelldatachange 핸들러
//  - setCellChecked 로 chk Cell 값이 변경되기 직전 호출됨
//  - par_cancel='true'(취소) 면 false 반환 → 변경 취소(oldValue 유지)
//  - par_cancel='false'(허용) 면 return 없음 → 변경 적용(oldValue -> newValue)
scwin.dlt_bind_onbeforecelldatachange = function (info) {
    let isCancel = (par_cancel.getValue() === 'true');

    if (isCancel) {
        wf_body_bottom.getObj("scwin").setReturnValue(
            "[onbeforecelldatachange] colID=" + info.colID + " 변경 취소(false 반환): oldValue " + info.oldValue + " 유지");
        // false 반환 시 변경 취소
        return false;
    }

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[onbeforecelldatachange] colID=" + info.colID + " 변경: oldValue " + info.oldValue + " -> newValue " + info.newValue);
    return true;
}



// setCellChecked 실행 : par_rowIndex / par_ckecked / par_cancel
//  - chk 컬럼('chk') 대상으로 setCellChecked 호출 → onbeforecelldatachange 발생
//  - 호출 전후 getCellData 비교로 취소(불변)/허용(변경) 확인
scwin.btn_setCellChecked_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let ckecked = (par_ckecked.getValue() === 'true');

    // 호출 전 DataList 저장값
    let beforeData = dlt_bind.getCellData(rowIndex, "chk");

    // setCellChecked 실행 (Column ID 'chk')
    target1.setCellChecked(rowIndex, 'chk', ckecked);

    // 호출 후 DataList 저장값
    let afterData = dlt_bind.getCellData(rowIndex, "chk");

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellChecked(" + rowIndex + ", 'chk', " + ckecked + ") → 저장값 " + beforeData + " -> " + afterData);
}
